create table base_mat
(
    mat_id         bigint auto_increment comment '主键'
        primary key,
    mat_code       varchar(64)                     null comment '物料编码',
    mat_name       varchar(128)                    null comment '物料描述',
    fd_code        varchar(64)                     null comment '财务编码',
    fig_num        varchar(64)                     null comment '图号',
    mat_group      varchar(32)                     null comment '物料组',
    mat_class      varchar(32)                     null comment '分类',
    unit_code      varchar(32)                     null comment '基本单位',
    gross_weight   decimal(24, 6) default 0.000000 null comment '毛重',
    safety_stock   decimal(24, 6) default 0.000000 null comment '安全库存',
    standard_price decimal(24, 6) default 0.000000 null comment '标准价',
    del_flag       char           default '0'      null comment '删除标识',
    create_by      varchar(64)                     null comment '创建人',
    create_time    datetime                        null comment '创建时间',
    update_by      varchar(64)                     null comment '修改人',
    update_time    datetime                        null comment '修改时间',
    max_stock      decimal(12, 4)                  null comment '库存上限'
)
    comment '物料主数据' collate = utf8mb4_general_ci
                         row_format = DYNAMIC;

create index MAT_CODE
    on base_mat (mat_code);

